<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
const router=useRouter()
import type {LearningMessage,LearningSession} from '@note-flow/core/ai-learning'
import {aiLocalScope} from '../services/aiClientConfig'
import {openLearningProposal,saveLearningProposal,generateTaskProposal,commitLearningProposal,learningOperation,cloneLearningProposal,type LearningProposal,type ActionOperation} from '../services/learningActions'
import {localAiWorkspace,type AreaEntity,type ProjectEntity} from '../services/workspace'
const dialog=ref<HTMLDialogElement>(),proposal=ref<LearningProposal>(),operation=ref<ActionOperation>(),busy=ref(false),error=ref(''),areas=ref<AreaEntity[]>([]),projects=ref<ProjectEntity[]>([])
const frozen=computed(()=>Boolean(operation.value)),availableProjects=computed(()=>projects.value.filter(v=>v.status!=='archived'&&(!proposal.value?.areaUid||v.areaUid===proposal.value.areaUid)))
const succeeded=computed(()=>operation.value?.results.filter(v=>v.status==='saved').length||0)
let timer:ReturnType<typeof setTimeout>|undefined,controller:AbortController|undefined,loading=false
async function open(kind:LearningProposal['kind'],session:LearningSession,message:LearningMessage){loading=true;error.value='';try{const scope=aiLocalScope(),value=await openLearningProposal(kind,session,message),result=await learningOperation(value.uid),targets=await localAiWorkspace();if(scope!==aiLocalScope())throw Error('本地空间已切换');proposal.value=value;operation.value=result;areas.value=targets.areas.filter(v=>!v.archived);projects.value=targets.projects;dialog.value?.showModal()}catch(source){error.value=source instanceof Error?source.message:'无法打开成果';dialog.value?.showModal()}finally{loading=false}}
watch(proposal,()=>{if(loading||!proposal.value||frozen.value)return;clearTimeout(timer);timer=setTimeout(()=>{if(proposal.value)void saveLearningProposal(proposal.value).catch(source=>error.value=source.message)},250)},{deep:true})
async function generate(){if(!proposal.value||busy.value)return;if(!window.confirm('将所选回答发送至当前模型，生成任务草稿？这可能产生费用，生成后仍需确认保存。'))return;busy.value=true;error.value='';controller=new AbortController();try{proposal.value=await generateTaskProposal(proposal.value,controller.signal)}catch(source){error.value=source instanceof Error?source.message:'生成失败'}finally{busy.value=false}}
function addTask(){proposal.value?.tasks.push({key:crypto.randomUUID(),selected:true,title:'',description:'',priority:0,estimatedMinutes:null,startAt:null,dueAt:null,parentKey:null})}
async function commit(){if(!proposal.value||busy.value)return;busy.value=true;error.value='';clearTimeout(timer);try{await saveLearningProposal(proposal.value);operation.value=await commitLearningProposal(proposal.value)}catch(source){error.value=source instanceof Error?source.message:'保存失败';operation.value=await learningOperation(proposal.value.uid)}finally{busy.value=false}}
async function copyDraft(){if(!proposal.value)return;proposal.value=await cloneLearningProposal(proposal.value);operation.value=undefined}
function close(){if(busy.value){controller?.abort();return}if(proposal.value&&!frozen.value)void saveLearningProposal(proposal.value);dialog.value?.close()}
onBeforeUnmount(()=>{clearTimeout(timer);controller?.abort()})
defineExpose({open})
</script>
<template><dialog ref="dialog" class="learning-action-dialog" aria-labelledby="learning-action-title" @cancel.prevent="close"><header><div><h3 id="learning-action-title">{{proposal?.kind==='tasks'?'规划任务':'沉淀为知识'}}</h3><small>编辑并确认后保存到当前本地空间</small></div><button aria-label="关闭成果预览" :disabled="busy" @click="close">×</button></header><p v-if="error" role="alert">{{error}}</p><template v-if="proposal"><section class="action-fields"><fieldset :disabled="busy||frozen"><div class="target-row"><label>领域<select v-model="proposal.areaUid" @change="proposal.projectUid=''"><option value="">不指定</option><option v-for="area in areas" :key="area.uid" :value="area.uid">{{area.name}}</option></select></label><label v-if="proposal.kind==='tasks'">项目<select v-model="proposal.projectUid"><option value="">不指定</option><option v-for="project in availableProjects" :key="project.uid" :value="project.uid">{{project.name}}</option></select></label></div><template v-if="proposal.kind==='knowledge'"><label>知识标题<input v-model="proposal.title" maxlength="200" aria-label="知识标题"/></label><label>一句话结论<textarea v-model="proposal.conclusion" maxlength="1000" rows="2" aria-label="知识结论"/></label><label>正文<textarea v-model="proposal.content" maxlength="50000" rows="7" aria-label="知识正文"/></label><div class="target-row"><label>适用场景<textarea v-model="proposal.applicability" maxlength="4000" rows="2"/></label><label>限制与待验证<textarea v-model="proposal.limitations" maxlength="4000" rows="2"/></label></div><small>保存为独立知识，状态为草稿、低置信度；不自动标记已验证。</small></template><template v-else><div class="action-toolbar"><button type="button" @click="generate">根据回答生成任务草稿</button><button type="button" :disabled="proposal.tasks.length>=20" @click="addTask">手动添加任务</button><small>最多 20 项，可勾选需要保存的任务</small></div><article v-for="(task,index) in proposal.tasks" :key="task.key" class="task-proposal"><div class="task-title"><input v-model="task.selected" type="checkbox" :aria-label="'选择任务 '+(index+1)"/><input v-model="task.title" maxlength="200" :aria-label="'任务标题 '+(index+1)" placeholder="任务标题"/><button type="button" :aria-label="'移除任务 '+(index+1)" @click="proposal.tasks.splice(index,1)">×</button></div><label>描述与验收标准<textarea v-model="task.description" maxlength="8000" rows="2" :aria-label="'任务描述 '+(index+1)"/></label><div class="task-grid"><label>优先级<select v-model="task.priority"><option :value="0">无</option><option :value="1">低</option><option :value="2">中</option><option :value="3">高</option></select></label><label>预计分钟<input v-model.number="task.estimatedMinutes" type="number" min="1" max="10080" @change="task.estimatedMinutes=task.estimatedMinutes||null"/></label><label>父任务<select v-model="task.parentKey"><option :value="null">无</option><option v-for="parent in proposal.tasks.filter(v=>v!==task&&!v.parentKey)" :key="parent.key" :value="parent.key">{{parent.title||'未命名任务'}}</option></select></label><label>开始时间<input v-model="task.startAt" type="datetime-local" @change="task.startAt=task.startAt||null"/></label><label>截止时间<input v-model="task.dueAt" type="datetime-local" @change="task.dueAt=task.dueAt||null"/></label></div></article></template></fieldset><details><summary>查看来源回答</summary><pre>{{proposal.message.content}}</pre></details><section v-if="operation" class="action-results" aria-live="polite"><b>已保存 {{succeeded}} / {{operation.results.length}}</b><p v-for="result in operation.results" :key="result.uid"><a v-if="result.status==='saved'" :href="router.resolve(result.kind==='knowledge'?`/knowledge/${result.uid}`:`/tasks?task=${result.uid}`).href">{{result.title}}</a><span v-else>{{result.title}}</span> · {{result.status==='saved'?'已保存':result.status==='failed'?'保存失败':'待执行'}}<small v-if="result.error">{{result.error}}</small></p><small>已确认内容已冻结，重试仅处理未成功项。</small></section></section><footer><button v-if="frozen" :disabled="busy" @click="copyDraft">复制为新草稿</button><button :disabled="busy" @click="close">{{frozen?'关闭':'稍后继续'}}</button><button v-if="!operation||succeeded<operation.results.length" class="primary" :disabled="busy" @click="commit">{{busy?'处理中…':operation?'重试未成功项':proposal.kind==='tasks'?'确认创建所选任务':'确认创建知识'}}</button><button v-if="busy&&controller" @click="controller.abort()">停止生成</button></footer></template></dialog></template>
<style scoped>
.learning-action-dialog{width:min(800px,calc(100vw - 28px));max-height:88dvh;box-sizing:border-box;border:1px solid var(--pc-border,#e0e8e4);border-radius:16px;background:var(--pc-surface,#fff);color:var(--pc-text,#213e31);padding:22px;box-shadow:0 20px 70px #12332522}.learning-action-dialog::backdrop{background:#102a2340}header,footer,.target-row,.action-toolbar,.task-title{display:flex;align-items:center;gap:10px}header{justify-content:space-between}h3{margin:0 0 5px}small{font-size:12px;color:var(--pc-muted,#7c8c83)}button,input,textarea,select{font:inherit;color:inherit;border:1px solid var(--pc-border,#e0e8e4);border-radius:8px;background:transparent;padding:8px;box-sizing:border-box}button{cursor:pointer}button:disabled,fieldset:disabled{opacity:.65}header button{border:0;font-size:22px}fieldset{border:0;padding:0;margin:0;min-width:0}label{display:flex;flex-direction:column;gap:6px;font-size:12px;margin:12px 0;min-width:0}input,textarea,select{width:100%}textarea{resize:vertical;line-height:1.7}input[type=checkbox]{width:auto}.target-row>label{flex:1}.action-fields{max-height:62dvh;overflow:auto;padding-right:6px}.action-toolbar{flex-wrap:wrap;padding:12px 0}.task-proposal{padding:14px;border:1px solid var(--pc-border,#e0e8e4);border-radius:10px;margin-bottom:12px}.task-title input:not([type=checkbox]){flex:1}.task-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.task-grid label{margin:4px 0}details{font-size:12px;margin:16px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;max-height:160px;overflow:auto}.action-results{padding:14px;background:var(--pc-bg,#f3f7f4);border-radius:10px;font-size:13px}.action-results small{display:block;margin-top:5px}footer{justify-content:flex-end;padding-top:18px;flex-wrap:wrap}.primary{background:var(--pc-primary,#176954);color:white;border:0}[role=alert]{font-size:13px;color:#b04f43}@media(max-width:600px){.task-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.learning-action-dialog{padding:15px}.action-fields{max-height:60dvh}}
</style>
